update public.learning_paths
set
  title = 'Biological Psychology / Neuroscience',
  goal = 'Biological Psychology / Neuroscience',
  summary = 'The syllabus covers biological psychology and levels of explanation; neurons, synapses, and psychopharmacology; neuroanatomy; neuroscience methods; sensory and motor systems; sleep and consciousness; emotion, stress, and reward; learning and memory; cognitive and affective neuroscience; developmental, genetic, hormonal, and social neuroscience; mental health and neurodiversity; neurological disorders; and an integrative case portfolio.',
  data = $biopjson${"slug": "biological-psychology-neuroscience", "title": "Biological Psychology / Neuroscience", "description": "The syllabus covers biological psychology and levels of explanation; neurons, synapses, and psychopharmacology; neuroanatomy; neuroscience methods; sensory and motor systems; sleep and consciousness; emotion, stress, and reward; learning and memory; cognitive and affective neuroscience; developmental, genetic, hormonal, and social neuroscience; mental health and neurodiversity; neurological disorders; and an integrative case portfolio.", "topics": [{"id": "e470673e-b87e-4a9c-9657-357f4d670782", "type": "topic", "title": "Biological Psychology, Neuroscience, and Levels of Explanation", "description": "Students learn how brain, body, genes, environment, development, and behavior fit together without reducing psychology to one level.", "children": [{"id": "9a1658ed-c87f-4c94-b7b1-22ffec6745ce", "type": "subtopic", "title": "Field orientation", "children": [{"id": "48f0191b-8b34-4f18-95f6-12cd38dc25cc", "type": "concept", "title": "Biopsychology, behavioral neuroscience, cognitive neuroscience, and neuropsychology"}, {"id": "a7c61fd5-31e7-4140-8be3-e44feaf64e63", "type": "concept", "title": "Behavior, cognition, affect, physiology, and environment"}, {"id": "fbe0fd6e-a746-4f8a-a9de-60b91537dfaf", "type": "concept", "title": "Basic, clinical, and translational questions"}], "description": "The point is to understand biological psychology as the bridge between behavior and nervous-system mechanisms."}, {"id": "43a3e1ea-6577-40d1-b4f8-cb98f812318b", "type": "subtopic", "title": "Levels of analysis", "children": [{"id": "3379b959-29e8-4288-a19b-9c1f0b71f340", "type": "concept", "title": "Genes, cells, circuits, systems, behavior, and society"}, {"id": "66af5f82-2425-48d8-aa2d-3d65a7330b31", "type": "concept", "title": "Reductionism and emergent explanation"}, {"id": "0e4b2c20-c2c1-44f8-a56c-f8a5fa9bf0f4", "type": "concept", "title": "Biopsychosocial models"}], "description": "Students learn to move between molecules, circuits, organisms, and culture."}, {"id": "2d510518-067e-4025-a5a6-e89db8b4c1b9", "type": "subtopic", "title": "Scientific reasoning", "children": [{"id": "84e07b93-5c00-4c12-a655-1400046afe10", "type": "concept", "title": "Correlation versus causation"}, {"id": "88fa9dec-d258-4b61-8c51-283cecba1a75", "type": "concept", "title": "Converging evidence across methods"}, {"id": "6e698ced-0bfb-44d3-abbb-6daddb027a05", "type": "concept", "title": "Replication and open science"}], "description": "Neuroscience claims require evidence, skepticism, and careful causal language."}]}, {"id": "fc7c915e-b64d-49e2-b7bc-f6ce2214f228", "type": "topic", "title": "Neurons, Glia, Membranes, and Neural Signaling", "description": "This module builds the cellular foundation for understanding how nervous systems encode, transmit, and regulate information.", "children": [{"id": "e0eb8577-403a-4593-83c8-8f3123e2209f", "type": "subtopic", "title": "Neural cells", "children": [{"id": "f087deb8-29d3-44ca-b284-7113a2cca834", "type": "concept", "title": "Neurons, astrocytes, oligodendrocytes, microglia, and Schwann cells"}, {"id": "08498e56-859c-4dec-89b4-f62280d2d90a", "type": "concept", "title": "Dendrites, soma, axon, myelin, and terminals"}, {"id": "978241e2-c5d4-4c56-9304-2d8a3e21a409", "type": "concept", "title": "Support, metabolism, immune signaling, and plasticity"}], "description": "Students learn what neurons and glia contribute to brain function."}, {"id": "bd1a91c6-5db0-4e3a-8dbc-b70fbc7aa9da", "type": "subtopic", "title": "Membrane potentials", "children": [{"id": "37e625dc-ff13-41f8-a52e-149600ab7fe6", "type": "concept", "title": "Resting potential"}, {"id": "31ec7323-6aff-4eee-91b4-f5d17c521f8a", "type": "concept", "title": "Ion channels and electrochemical gradients"}, {"id": "16790087-1897-4647-b629-982ebbadd392", "type": "concept", "title": "Depolarization, hyperpolarization, and threshold"}], "description": "Electrical signaling begins with ionic gradients and membrane permeability."}, {"id": "7a227986-533e-40e4-a58e-eaa128b71f9a", "type": "subtopic", "title": "Action potentials", "children": [{"id": "9b8d8965-5da6-46c9-8ba9-99051933db00", "type": "concept", "title": "Voltage-gated sodium and potassium channels"}, {"id": "ce528d7b-e0a9-4538-8d0b-9da208121d49", "type": "concept", "title": "Refractory periods and conduction velocity"}, {"id": "f78c0ea8-3ee8-482d-b7fd-f75ef3d8b641", "type": "concept", "title": "Saltatory conduction and myelination"}], "description": "Students learn how neurons send fast, all-or-none signals."}]}, {"id": "bb080b70-199f-4535-9162-e1b199218203", "type": "topic", "title": "Synaptic Transmission, Neurotransmitters, Receptors, and Psychopharmacology", "description": "Students learn how chemical signaling shapes behavior and how drugs alter neural systems.", "children": [{"id": "523c7e92-8680-454d-a267-4c5250751744", "type": "subtopic", "title": "Synapses", "children": [{"id": "a78d3be6-3040-4387-971a-34eee8c9a383", "type": "concept", "title": "Vesicle release and calcium"}, {"id": "794737a4-d091-484a-86da-946de6d5b911", "type": "concept", "title": "Excitatory and inhibitory postsynaptic potentials"}, {"id": "e0abc788-ee5b-43b0-90f8-4ea1d0ff5946", "type": "concept", "title": "Temporal and spatial summation"}], "description": "Synapses convert neural activity into communication between cells."}, {"id": "a76cd2ab-70b6-4a10-950e-5b2418f21d13", "type": "subtopic", "title": "Transmitters and receptors", "children": [{"id": "40a76201-6eb5-4e0f-89f1-f1c295261143", "type": "concept", "title": "Glutamate, GABA, dopamine, serotonin, norepinephrine, acetylcholine, and neuropeptides"}, {"id": "e9ab2d89-76a2-4089-8a8b-8a215513470b", "type": "concept", "title": "Ionotropic and metabotropic receptors"}, {"id": "f68cd10e-ca39-4d96-99c0-beaa38fc40a2", "type": "concept", "title": "Reuptake, degradation, and receptor regulation"}], "description": "Different neurotransmitter systems support different behavioral functions."}, {"id": "8638d66d-0e61-4c8a-93c3-0775cfb62552", "type": "subtopic", "title": "Drug action", "children": [{"id": "30269b92-1f29-4b3d-85c6-14d778860fb4", "type": "concept", "title": "Agonists, antagonists, tolerance, dependence, and withdrawal"}, {"id": "1a39e94a-0909-4064-a118-5917c6675e5e", "type": "concept", "title": "Antidepressants, antipsychotics, anxiolytics, mood stabilizers, and stimulants"}, {"id": "25563912-77ba-476e-a3f1-1c62048e7c1a", "type": "concept", "title": "Ethics, placebo effects, adherence, and collaborative care boundaries"}], "description": "Psychopharmacology links molecules to symptoms, side effects, and behavior."}]}, {"id": "ed4d5a0e-ad05-4cd0-b54b-c1479579280d", "type": "topic", "title": "Neuroanatomy: Brain, Spinal Cord, Peripheral, and Autonomic Systems", "description": "This topic maps major nervous-system structures to behavior, regulation, and clinical signs.", "children": [{"id": "28d7302b-e0e4-494a-bd4d-752d856058f1", "type": "subtopic", "title": "Brain organization", "children": [{"id": "1aebd09d-9824-450d-9094-cd1c2331def0", "type": "concept", "title": "Cerebral cortex, lobes, and major landmarks"}, {"id": "8b092e3e-15a8-40cc-ac18-ece503fcb69f", "type": "concept", "title": "Brainstem, thalamus, hypothalamus, cerebellum, and basal ganglia"}, {"id": "58592919-288f-4406-bf4b-e0d5fd6d8f61", "type": "concept", "title": "White matter tracts and ventricular system"}], "description": "Students learn the structural vocabulary needed to read brain-behavior evidence."}, {"id": "6640c9da-2a95-4c8e-b932-9500801dff71", "type": "subtopic", "title": "Spinal and peripheral systems", "children": [{"id": "73c18c1d-7d3a-4a17-9589-d19b38ce70bd", "type": "concept", "title": "Spinal cord organization"}, {"id": "6df719ee-5632-4f93-9e83-ed7034889e4e", "type": "concept", "title": "Peripheral nerves and reflex arcs"}, {"id": "e47b66fa-5a95-4e2c-9d3c-87db54e59682", "type": "concept", "title": "Cranial nerves overview"}], "description": "The nervous system extends beyond the brain into body-wide sensing and action."}, {"id": "96efd6c0-962a-4d49-b98e-4ba5cd6cf1fa", "type": "subtopic", "title": "Autonomic regulation", "children": [{"id": "84491e05-2047-4d96-9340-6cdf761f71c9", "type": "concept", "title": "Sympathetic and parasympathetic systems"}, {"id": "898ccc97-edb9-42a3-b908-ec21769d1342", "type": "concept", "title": "Enteric nervous system"}, {"id": "9c3bacf6-6ad5-4fe7-ad93-6df5cbb73627", "type": "concept", "title": "Homeostasis and allostasis"}], "description": "Autonomic systems regulate arousal, stress, digestion, cardiovascular function, and homeostasis."}]}, {"id": "68e14d53-5323-4d5a-8e75-fbafd6fdd122", "type": "topic", "title": "Neuroscience Methods, Measurement, Ethics, and Open Science", "description": "Students learn how neuroscience evidence is generated, interpreted, and limited by method, design, and ethics.", "children": [{"id": "a30687ad-888b-453b-9e8e-704f2bcf339e", "type": "subtopic", "title": "Human neuroscience methods", "children": [{"id": "ac3319ad-9d50-4a2f-9791-5349dfcf0b5d", "type": "concept", "title": "fMRI, PET, EEG, MEG, TMS, lesion studies, and neuropsychology"}, {"id": "b2128863-5c17-4dee-878b-55e6694c680f", "type": "concept", "title": "Spatial and temporal resolution"}, {"id": "648816dc-1ea5-4acf-967f-56351aa136f8", "type": "concept", "title": "Reverse inference and interpretation limits"}], "description": "Students learn what different tools can and cannot tell us."}, {"id": "e98ed5be-7fa1-4e36-a572-387b8c9cb16b", "type": "subtopic", "title": "Cellular and animal methods", "children": [{"id": "b409f752-c6e9-4c42-8674-08d8d9b001a2", "type": "concept", "title": "Electrophysiology and optogenetics overview"}, {"id": "77b5f1e3-27e8-4c4f-8268-bc89d37c9086", "type": "concept", "title": "Molecular and genetic tools"}, {"id": "e20b5a31-13bc-4620-bd51-458f1037a592", "type": "concept", "title": "Behavioral assays and translation limits"}], "description": "Mechanistic neuroscience often depends on controlled model systems."}, {"id": "d245d740-758c-48f1-ab49-99a4a51b0918", "type": "subtopic", "title": "Ethics and transparency", "children": [{"id": "d293e884-f1aa-476b-ad36-4a8a0f5e971d", "type": "concept", "title": "Human subjects and neurodata privacy"}, {"id": "791aa41e-3eee-4c11-b3c0-a6052fe61274", "type": "concept", "title": "Animal welfare and the 3Rs"}, {"id": "443d1b2a-1a6e-40f6-b0bc-c0e535c5981c", "type": "concept", "title": "Preregistration, data management, and responsible communication"}], "description": "Neuroscience research requires careful consent, privacy, animal ethics, and reproducibility."}]}, {"id": "3f36d977-b5c7-44b6-a526-44aa0414288c", "type": "topic", "title": "Sensory Systems: Vision, Audition, Somatosensation, Taste, and Smell", "description": "This module explains how nervous systems transform physical energy into perception and action-relevant information.", "children": [{"id": "67eecbfa-8f27-4917-b3fd-b753d33ba71c", "type": "subtopic", "title": "Sensory coding", "children": [{"id": "4d1d2415-708e-458b-95f0-f8fde98c46ae", "type": "concept", "title": "Transduction and receptive fields"}, {"id": "621c11c7-0c78-4064-ba2d-fb3edda16e67", "type": "concept", "title": "Labeled lines and population coding"}, {"id": "779d1048-a20c-4985-9c56-912ca8064346", "type": "concept", "title": "Adaptation and thresholds"}], "description": "Students learn how receptors convert physical stimuli into neural signals."}, {"id": "fa3ed464-63eb-4312-83fd-2b6f4c89b8e8", "type": "subtopic", "title": "Vision and audition", "children": [{"id": "03b7840f-430a-4066-b348-54ca80558c76", "type": "concept", "title": "Retina, LGN, visual cortex, and dorsal/ventral streams"}, {"id": "a278025a-6ba6-4de7-b8b2-812aeb072ceb", "type": "concept", "title": "Cochlea, auditory nerve, brainstem pathways, and auditory cortex"}, {"id": "aebf1771-63b8-470f-9798-c07119715c5f", "type": "concept", "title": "Localization, object recognition, and attention"}], "description": "These systems show how perception is constructed from specialized pathways."}, {"id": "520e212d-9f61-476b-bc2c-2c81aea8a398", "type": "subtopic", "title": "Body and chemical senses", "children": [{"id": "55124d16-04b5-4d75-af5d-3682247414da", "type": "concept", "title": "Touch, pain, proprioception, and temperature"}, {"id": "539f9e23-bec3-4a66-b824-a12b56acc8a4", "type": "concept", "title": "Taste pathways and flavor"}, {"id": "b00ba25a-5b13-42d7-9efc-b45fb1ddade7", "type": "concept", "title": "Olfaction, memory, and emotion"}], "description": "Somatosensation, taste, and smell connect perception to survival and affect."}]}, {"id": "764cc3c0-d6d3-4bc9-81f2-3726a83ac0d8", "type": "topic", "title": "Motor Systems, Movement, Basal Ganglia, Cerebellum, and Action Control", "description": "Students study how the nervous system plans, initiates, coordinates, and learns movement.", "children": [{"id": "3ce145d8-dd05-47a1-9d81-c75b15d71be4", "type": "subtopic", "title": "Motor pathways", "children": [{"id": "6f134635-b3ef-4c51-a8f1-dbda8533f40a", "type": "concept", "title": "Motor cortex and corticospinal tract"}, {"id": "ed8323b8-5607-43aa-aa01-85c7903618fa", "type": "concept", "title": "Spinal reflexes and central pattern generators"}, {"id": "247cf986-44bf-4c81-b686-5282b2b10911", "type": "concept", "title": "Motor units and neuromuscular junction"}], "description": "Movement depends on hierarchical control from cortex to spinal cord."}, {"id": "8df3b299-0eba-474e-ab6d-e16f33b0ff7a", "type": "subtopic", "title": "Basal ganglia and cerebellum", "children": [{"id": "046c8a7c-20e9-4da4-9c73-45da38a3212f", "type": "concept", "title": "Basal ganglia loops and reinforcement"}, {"id": "fd4ab9f5-9336-4fcc-82b7-4b0f37382f7c", "type": "concept", "title": "Cerebellar prediction and error correction"}, {"id": "9d6715ec-ce4b-44ad-bba3-5e6825123a99", "type": "concept", "title": "Parkinsonian and cerebellar signs"}], "description": "These systems tune action selection, timing, coordination, and learning."}, {"id": "8ae2cd56-7419-4af8-a531-c54ecf6bee19", "type": "subtopic", "title": "Action and behavior", "children": [{"id": "1c7f2af6-2f6f-4dd2-bf08-c3a293c9b8d9", "type": "concept", "title": "Motor planning"}, {"id": "bf3ee978-2195-453a-84b1-a74b85fe29b4", "type": "concept", "title": "Skill learning and practice"}, {"id": "be56cda4-78f9-4b8f-8ed1-dfc7dcce58d8", "type": "concept", "title": "Fatigue, feedback, and adaptation"}], "description": "Motor systems connect intention, perception, learning, and embodied cognition."}]}, {"id": "bce455a0-0c91-432f-b01f-34fc91935318", "type": "topic", "title": "Sleep, Circadian Rhythms, Arousal, and Consciousness", "description": "This topic connects brain rhythms, sleep architecture, biological clocks, attention, and altered states.", "children": [{"id": "3d173019-e2fb-433e-a088-d622cd1cdf71", "type": "subtopic", "title": "Sleep architecture", "children": [{"id": "3f67ab45-bf62-4758-a247-1e8ea24db6b8", "type": "concept", "title": "NREM and REM sleep"}, {"id": "bff55c34-9c3c-4689-b4a7-e2d8c44c4584", "type": "concept", "title": "EEG rhythms"}, {"id": "13c07649-83ad-410d-9d29-7043bcb10a90", "type": "concept", "title": "Sleep cycles and development"}], "description": "Students learn how sleep stages support brain and body function."}, {"id": "937aafa8-7266-4e17-8bce-1c0679b0f954", "type": "subtopic", "title": "Circadian biology", "children": [{"id": "487e1d25-021d-4395-9cad-8f0e05ddb1f2", "type": "concept", "title": "Suprachiasmatic nucleus"}, {"id": "461cf041-b338-432d-8cd7-6ba715500532", "type": "concept", "title": "Melatonin, light, and zeitgebers"}, {"id": "2e378265-434b-495d-bcd4-9f0705c7fcfd", "type": "concept", "title": "Shift work, jet lag, and chronotype"}], "description": "Biological clocks coordinate behavior with environmental time."}, {"id": "3a60b41f-5d9f-4ffd-958b-fb886f6da0f3", "type": "subtopic", "title": "Arousal and consciousness", "children": [{"id": "eb126cf8-c5b0-4483-b3c3-8b1de29c3503", "type": "concept", "title": "Reticular activating system"}, {"id": "2c0dc467-2214-4737-9996-3cd726ad001d", "type": "concept", "title": "Coma, anesthesia, and altered consciousness overview"}, {"id": "2e58f2d5-058b-43f7-8abe-fa8a9a5980da", "type": "concept", "title": "Dreaming, meditation, and psychoactive states"}], "description": "Arousal systems shape attention, awareness, and altered states."}]}, {"id": "62be8e82-6985-4cf0-add3-c000bbd7a57c", "type": "topic", "title": "Emotion, Stress, Motivation, Reward, and the Limbic System", "description": "Students learn how affective and motivational systems guide survival, learning, social behavior, and mental health.", "children": [{"id": "a649135b-5e15-4d19-86df-4307b84c7773", "type": "subtopic", "title": "Emotion systems", "children": [{"id": "b77c5c78-d182-408b-bee7-3db335f50628", "type": "concept", "title": "Amygdala, prefrontal cortex, insula, and limbic circuits"}, {"id": "dd7f5f50-494d-4f91-bcd7-cbc2cc440f48", "type": "concept", "title": "Fear, threat, reward, and appraisal"}, {"id": "74d4b4f0-f94c-40bf-b6d1-a4c0b74c7d06", "type": "concept", "title": "Constructionist and basic-emotion debates"}], "description": "Students learn neural accounts of emotion without treating one structure as the whole story."}, {"id": "d57f12b2-3c97-4e7f-9b91-7b7fc7b29fe3", "type": "subtopic", "title": "Stress physiology", "children": [{"id": "8a798add-0bc7-4819-b80c-8e672d3b9f64", "type": "concept", "title": "HPA axis and cortisol"}, {"id": "3c3db46e-5ead-49c0-9656-3f2e7a11468b", "type": "concept", "title": "Acute versus chronic stress"}, {"id": "a7cff070-d2ff-49cc-b5d7-0e9d22effbdc", "type": "concept", "title": "Allostatic load and resilience"}], "description": "Stress links brain, endocrine, immune, and behavioral systems."}, {"id": "15a89f08-2c2c-419a-a09b-48be38dffdd9", "type": "subtopic", "title": "Motivation and reward", "children": [{"id": "ef5c83d4-1799-47c8-9a8e-142b17280d90", "type": "concept", "title": "Dopamine and prediction error"}, {"id": "d0061f30-6140-4044-8f8e-7e4a76a9e14a", "type": "concept", "title": "Hunger, thirst, sex, attachment, and incentive salience"}, {"id": "e4735e11-045b-4810-9906-381e05a42818", "type": "concept", "title": "Self-control and delay discounting"}], "description": "Reward systems guide learning, effort, habit, and addiction risk."}]}, {"id": "19bde1b8-f31b-450f-b80e-962b72936ec9", "type": "topic", "title": "Learning, Memory, Plasticity, and the Hippocampal-Cortical System", "description": "This module connects synaptic plasticity to memory systems, skill learning, development, and recovery.", "children": [{"id": "5e61f2b8-d424-49f1-9805-eec81253d475", "type": "subtopic", "title": "Memory systems", "children": [{"id": "cb4ea437-f985-474e-a5fd-54d926d1f110", "type": "concept", "title": "Working, episodic, semantic, procedural, and emotional memory"}, {"id": "de2e84b1-e892-4629-901e-d20f3ecb1bc7", "type": "concept", "title": "Hippocampus, cortex, amygdala, and striatum"}, {"id": "ff8e71f8-c935-4be8-b781-ef69c6ecdb45", "type": "concept", "title": "Encoding, consolidation, retrieval, and reconsolidation"}], "description": "Different forms of memory depend on different neural circuits."}, {"id": "fcaf71ca-b7fa-414c-9f67-96e67fd351a6", "type": "subtopic", "title": "Plasticity mechanisms", "children": [{"id": "a1434e77-8d8e-4c2c-9343-dec9b1a5ae77", "type": "concept", "title": "Long-term potentiation and depression"}, {"id": "88072096-e3b6-4905-97ae-c8b3cf99f58c", "type": "concept", "title": "Experience-dependent plasticity"}, {"id": "7327e4bd-32a9-4214-91f6-a3df15d08158", "type": "concept", "title": "Critical periods and adult plasticity"}], "description": "Learning changes synapses, circuits, and behavior."}, {"id": "c9d8d44c-ae8c-4d75-b50e-16c0e669f4b9", "type": "subtopic", "title": "Applications", "children": [{"id": "96ba549b-5306-4d09-8626-1434b08da533", "type": "concept", "title": "Sleep and consolidation"}, {"id": "52635d56-c94c-4457-b330-66ca3c5ed7ab", "type": "concept", "title": "Stress effects on memory"}, {"id": "c21379c6-4cc3-4b23-b63a-0f4756a676df", "type": "concept", "title": "Rehabilitation and compensatory strategies"}], "description": "Memory science helps explain education, therapy, aging, and recovery."}]}, {"id": "c5cff22c-58ff-4500-b235-5361cceecbb2", "type": "topic", "title": "Cognitive and Affective Neuroscience: Attention, Language, Decision-Making, and Executive Control", "description": "Students integrate behavioral psychology with neural systems supporting cognition and emotion regulation.", "children": [{"id": "8aaa7ef2-2372-471c-8ad5-13d5a890d4ac", "type": "subtopic", "title": "Attention and executive control", "children": [{"id": "e26d4044-6b93-4373-9206-80844acdbf2b", "type": "concept", "title": "Prefrontal cortex and control networks"}, {"id": "4e1d04b0-d3f8-46cc-92f1-069cf67be6ec", "type": "concept", "title": "Selective attention and working memory"}, {"id": "6d17857a-fbac-4adf-aa9c-7c2a9726c704", "type": "concept", "title": "Cognitive flexibility and inhibition"}], "description": "Students learn how the brain selects, sustains, and regulates information processing."}, {"id": "d3a52d51-1f4c-463d-afea-a168fe9ffc0c", "type": "subtopic", "title": "Language and lateralization", "children": [{"id": "876f2215-5728-41d7-8c94-a6b743d0cb33", "type": "concept", "title": "Broca and Wernicke regions in context"}, {"id": "2b571065-137c-4b68-8833-507df2b0857e", "type": "concept", "title": "Reading, speech, and semantic networks"}, {"id": "a9061c93-cd18-45ac-84b0-d773daa30f87", "type": "concept", "title": "Aphasia and lateralization"}], "description": "Language illustrates distributed networks and hemispheric specialization."}, {"id": "e330e118-6218-4bcf-935e-13a9dccb4b91", "type": "subtopic", "title": "Decision-making", "children": [{"id": "6c3a5c17-d26c-4cd6-865a-ed357ae382d6", "type": "concept", "title": "Reward valuation"}, {"id": "76ea4cdc-7be3-4a01-ba